{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '이미 안 될 거라고 알고 있었다는 느낌이 계획을 세울 때부터 함께 있었는지' 질문하고 있음. 내담자의 핵심 신념 '나는 하기 싫고 답답한 일을 스스로 하게 만들 수 없는 사람이다'가 계획 수립 순간부터 이미 작동하고 있었는지를 탐색하는 질문과 직접 연결됨. 성장 배경에서 '나는 원래 진득하게 못 하는 애'라는 신념이 형성된 경향이 관련됨."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/situations/3"],
      "relevance": "상담사의 질문은 자기통제·자기훈련의 결핍이 계획 단계에서부터 이미 인식되고 있었는지를 묻고 있음. 상황 사례에서 도서관 좌석을 등록한 순간부터 '결심을 지켜본 적이 없는데 이번이라고 될까'라는 생각이 함께 있었던 것이 자기통제 신념이 계획 시점부터 작동했음을 보여줌."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "'이미 안 될 거라고 알고 있었다'는 체념은 불편함을 인내할 수 있는 한계가 손상되어 있다는 인식과 연결됨. 성장 배경에서 불편함을 피하면 된다는 규칙이 몸에 밴 것이 계획 시점부터 '안 될 것'을 전제하게 만드는 근거가 됨."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "'원래 이런 걸 못 하는 사람'이라는 내담자의 진술과 상담사의 질문이 연결되는 지점. '지루하고 답답한 것을 참고 하는 것은 불가능에 가까운 고통'이라는 태도가 계획 세우는 순간부터 '이미 안 될 거'라는 예감으로 작동했을 가능성을 탐색."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": [],
      "relevance": "'억지로 붙잡고 앉아 있으면 어차피 집중도 안 되고 괴롭기만 할 뿐 결과도 엉망'이라는 부정적 가정은, 계획을 세우는 순간부터 '이렇게 해도 안 될 것'이라는 체념적 확신을 낳는 논리적 근거가 됨."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": [],
      "relevance": "'기분이 내키지 않으면 시작할 수 없다'는 규칙이 계획 수립 시점부터 적용되면, 계획을 세우는 행위 자체가 이미 '내키지 않으면 못 한다'는 전제 하에 이루어지므로 '이미 안 될 거'라는 느낌이 계획과 동시에 존재하게 됨."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "새 계획표 작성으로 죄책감을 달래는 전략이 상담사의 질문과 직접 연결됨. 내담자가 '이번엔 다를까 싶어서 계획표를 만들면 잠깐 설레는데 몇 시간도 안 가서 무너진다'고 한 진술에서, 계획 세우는 순간의 설렘과 '이미 안 될 거'라는 체념이 동시에 존재했음을 시사."
    }
  ]
}

